-- WorthTrack schema v2 的真实建表语句（v1 全部表 + module_state）
-- 用途：迁移测试里造一个真正的 v2 库，再让 AppDatabase 升级到 v3，确认「只加表不动数据」。
-- 维护：只有新增 migration 时才需要新增 schema_v3.sql，**不要修改本文件**。
CREATE TABLE "accounts" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "name" TEXT NOT NULL, "type" INTEGER NOT NULL, "balance_minor" INTEGER NOT NULL DEFAULT 0, "note" TEXT NULL, "sort_order" INTEGER NOT NULL DEFAULT 0, "archived_at" INTEGER NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)));
CREATE TABLE "budgets" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "category_id" INTEGER NOT NULL REFERENCES categories (id), "amount_minor" INTEGER NOT NULL, "month" INTEGER NOT NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), UNIQUE ("category_id", "month"));
CREATE TABLE "categories" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "name" TEXT NOT NULL, "kind" INTEGER NOT NULL, "icon" TEXT NULL, "sort_order" INTEGER NOT NULL DEFAULT 0, "parent_id" INTEGER NULL REFERENCES categories (id), "archived_at" INTEGER NULL);
CREATE TABLE "module_state" ("module_id" TEXT NOT NULL, "enabled" INTEGER NOT NULL DEFAULT 1 CHECK ("enabled" IN (0, 1)), "sort_order" INTEGER NOT NULL DEFAULT 0, "first_enabled_at" INTEGER NULL, PRIMARY KEY ("module_id"));
CREATE TABLE "positions" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "market" INTEGER NOT NULL, "code" TEXT NOT NULL, "name" TEXT NOT NULL, "shares_cent" INTEGER NOT NULL, "cost_price_minor" INTEGER NOT NULL, "archived_at" INTEGER NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)), UNIQUE ("market", "code"));
CREATE TABLE "price_cache" ("symbol" TEXT NOT NULL, "price_minor" INTEGER NOT NULL, "updated_at" INTEGER NOT NULL, PRIMARY KEY ("symbol"));
CREATE TABLE "recurring_rules" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "name" TEXT NOT NULL, "type" INTEGER NOT NULL, "account_id" INTEGER NOT NULL REFERENCES accounts (id), "category_id" INTEGER NULL REFERENCES categories (id), "amount_minor" INTEGER NOT NULL, "frequency" INTEGER NOT NULL, "interval" INTEGER NOT NULL DEFAULT 1, "start_date" INTEGER NOT NULL, "next_run_at" INTEGER NOT NULL, "end_date" INTEGER NULL, "active" INTEGER NOT NULL DEFAULT 1 CHECK ("active" IN (0, 1)), "note" TEXT NULL);
CREATE TABLE "transactions" ("id" INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT, "type" INTEGER NOT NULL, "account_id" INTEGER NOT NULL REFERENCES accounts (id), "to_account_id" INTEGER NULL REFERENCES accounts (id), "category_id" INTEGER NULL REFERENCES categories (id), "amount_minor" INTEGER NOT NULL, "note" TEXT NULL, "occurred_at" INTEGER NOT NULL, "created_at" INTEGER NOT NULL DEFAULT (CAST(strftime('%s', CURRENT_TIMESTAMP) AS INTEGER)));
